// Tests of the key validation added to the library in revision 2. They run the classes EtalonFactory and AssocStego
// of the listing itself (extracted by extract.py) together with KeyValidation.cs and the BitVector stand-in.
//  T1  keys generated by the library are accepted; |P| distribution; cost of the validation
//  T2  keys written to a key file and read back are accepted and recognize the blocks formed with the original key
//  T3  keys not built by dichotomic partitioning: random masks (union of positions large) and masks drawn from a pool of
//      at most nine positions; the decision is compared with an independent check of condition (5) and of coverage
//  T4  key files with one flipped mask bit: rejected, accepted as a different key, and the effect on recognition
using System.Diagnostics;
using System.Text.Json;

int n = args.Length > 0 ? int.Parse(args[0]) : 100000;
string[] et = EtalonFactory.CreateDefaultEtalons10();
int L = et.Length;
var rng = new Random(20261109);
string dir = Path.Combine(Path.GetTempPath(), "keyval_tests");
Directory.CreateDirectory(dir);
int failures = 0;
var report = new Dictionary<string, object>();
void Check(bool ok, string what) { if (!ok) { failures++; Console.WriteLine("FAILED: " + what); } }

var proto = new AssocStego(et);
int c = proto.ContainerByteLength, bitLen = proto.etalonLength;
BitVector[] etalonVectors = proto.etalons;

// ---------------------------------------------------------------- T1
{
    var mHist = new long[17]; long rejected = 0;
    var sw = Stopwatch.StartNew();
    for (int k = 0; k < n; k++)
    {
        var st = new AssocStego(et);
        try { st.CreateKey(); mHist[st.KeyTable.M]++; }
        catch (KeyValidationException e) { rejected++; if (rejected < 5) Console.WriteLine("T1 rejected: " + e.Message); }
    }
    double sec = sw.Elapsed.TotalSeconds;
    // cost of the validation alone: building the table for a key already set
    var st0 = new AssocStego(et); st0.CreateKey();
    byte[] fk = st0.FlattenedKeysBytes, fme = st0.FlattenedMaskedEtalonsBytes;
    for (int w = 0; w < 2000; w++) KeyRecognitionTable.BuildOrThrow(fk, fme, c, L, bitLen);
    var times = new double[20];
    for (int r = 0; r < times.Length; r++)
    {
        var s2 = Stopwatch.StartNew();
        for (int w = 0; w < 1000; w++) KeyRecognitionTable.BuildOrThrow(fk, fme, c, L, bitLen);
        times[r] = s2.Elapsed.TotalMilliseconds;           // ms per 1000 builds = us per build
    }
    Array.Sort(times);
    Console.WriteLine($"T1: {n} generated keys, rejected {rejected}; |P|: " +
        string.Join(", ", Enumerable.Range(0, 17).Where(m => mHist[m] > 0).Select(m => $"{m}:{mHist[m]}")) +
        $"; generation with validation {sec:F1} s; table construction median {times[times.Length / 2]:F1} us (min {times[0]:F1}, max {times[^1]:F1})");
    Check(rejected == 0, "T1: a key generated by the library was rejected");
    report["T1"] = new { keys = n, rejected, mHist, tableBuildMedianUs = times[times.Length / 2], tableBuildMinUs = times[0], tableBuildMaxUs = times[^1] };
}

// ---------------------------------------------------------------- T2
{
    int keys = Math.Min(n, 1000), bytesPerKey = 10000; long mismatches = 0, tableDiff = 0;
    for (int k = 0; k < keys; k++)
    {
        var st = new AssocStego(et); var key = st.CreateKey();
        string path = Path.Combine(dir, "key.bin");
        st.SaveKeyToFile(path, key);
        var st2 = new AssocStego(et); st2.LoadKeyFromFile(path);
        var t1 = st.KeyTable; var t2 = st2.KeyTable;
        if (t1.M != t2.M || !t1.Table.SequenceEqual(t2.Table) || !t1.PositionByte.SequenceEqual(t2.PositionByte) || !t1.PositionBit.SequenceEqual(t2.PositionBit)) tableDiff++;
        var data = new byte[bytesPerKey]; rng.NextBytes(data);
        var block = new byte[st.HiddenByteLength];
        for (int i = 0; i < data.Length; i++)
        {
            st.HideByteToBuffer(data[i], block);
            byte bySearch = st2.DiscloseByteFromBuffer(block);
            int byTable = t2.Digit(block, 0) * 100 + t2.Digit(block, c) * 10 + t2.Digit(block, 2 * c);
            if (bySearch != data[i] || byTable != data[i]) mismatches++;
        }
    }
    Console.WriteLine($"T2: {keys} keys saved and loaded; tables differing {tableDiff}; recognition mismatches {mismatches} of {(long)keys * bytesPerKey} bytes");
    Check(tableDiff == 0 && mismatches == 0, "T2: round trip");
    report["T2"] = new { keys, bytesPerKey, tableDiff, mismatches };
}

// ---------------------------------------------------------------- T3
// independent checks: condition (5) and coverage of all patterns on P by brute force
bool Cond5(List<int>[] masks)
{
    for (int d = 0; d < L; d++)
        for (int t = d + 1; t < L; t++)
            if (!masks[d].Intersect(masks[t]).Any(p => etalonVectors[d].GetBit(p) != etalonVectors[t].GetBit(p))) return false;
    return true;
}
bool SignaturesDistinct(BitVector[] key)
{
    var seen = new HashSet<string>();
    for (int t = 0; t < L; t++) if (!seen.Add((etalonVectors[t] & key[t]).ToString())) return false;
    return true;
}
bool CoverAll(List<int>[] masks, List<int> P)
{
    for (int u = 0; u < (1 << P.Count); u++)
    {
        bool any = false;
        for (int t = 0; t < L && !any; t++)
            if (masks[t].All(p => (((u >> P.IndexOf(p)) & 1) == 1) == etalonVectors[t].GetBit(p))) any = true;
        if (!any) return false;
    }
    return true;
}
BitVector Vec(List<int> positions) { var v = new BitVector(bitLen); foreach (var p in positions) v.SetBit(p, true); return v; }
(long trials, long sigDistinct, long cond5, long accepted, long acceptedViolating5, long rejectedSatisfying5, long disagreeWithIndependent, Dictionary<string, long> reasons)
RunT3(int trials, Func<List<int>[]> draw, bool independentCoverage)
{
    long sig = 0, c5 = 0, acc = 0, accBad = 0, rejGood = 0, disagree = 0; var reasons = new Dictionary<string, long>();
    for (int k = 0; k < trials; k++)
    {
        var masks = draw();
        var key = masks.Select(Vec).ToArray();
        bool s = SignaturesDistinct(key), q = Cond5(masks);
        if (s) sig++; if (q) c5++;
        var st = new AssocStego(et); bool ok;
        try { st.Key = key; ok = true; }
        catch (KeyValidationException e)
        {
            ok = false;
            string r = e.Message.Contains("позиций") ? "more than L-1 positions" : e.Message.Contains("ни одному") ? "pattern matches no etalon" : e.Message.Contains("неоднозначно") ? "pattern matches several etalons" : "other";
            reasons[r] = reasons.GetValueOrDefault(r) + 1;
        }
        if (ok) acc++;
        if (ok && !q) accBad++;
        if (!ok && q) rejGood++;
        if (independentCoverage)
        {
            var P = masks.SelectMany(x => x).Distinct().ToList();
            bool expected = P.Count <= L - 1 && q && CoverAll(masks, P);
            if (expected != ok) disagree++;
        }
    }
    return (trials, sig, c5, acc, accBad, rejGood, disagree, reasons);
}
{
    // (a) random masks: weights 2-8, positions uniform over the etalon length
    var a = RunT3(n, () => Enumerable.Range(0, L).Select(_ => Enumerable.Range(0, bitLen).OrderBy(_ => rng.Next()).Take(rng.Next(2, 9)).ToList()).ToArray(), false);
    // (b) masks drawn from a pool of nine random positions, weights 2-8: |P| <= 9, so the table is always attempted
    var b = RunT3(n, () =>
    {
        var pool = Enumerable.Range(0, bitLen).OrderBy(_ => rng.Next()).Take(L - 1).ToList();
        return Enumerable.Range(0, L).Select(_ => pool.OrderBy(_ => rng.Next()).Take(rng.Next(2, 9)).ToList()).ToArray();
    }, true);
    foreach (var (name, r) in new[] { ("random masks", a), ("pool of nine positions", b) })
    {
        Console.WriteLine($"T3 {name}: {r.trials} keys; distinct signatures (original check) {r.sigDistinct}; condition (5) {r.cond5}; accepted {r.accepted}; " +
            $"accepted although (5) fails {r.acceptedViolating5}; rejected although (5) holds {r.rejectedSatisfying5}; disagreements with the independent check {r.disagreeWithIndependent}; reasons: " +
            string.Join(", ", r.reasons.Select(kv => $"{kv.Key} {kv.Value}")));
        Check(r.acceptedViolating5 == 0, $"T3 {name}: a key violating condition (5) was accepted");
        Check(r.disagreeWithIndependent == 0, $"T3 {name}: decision differs from the independent check");
    }
    report["T3_random"] = new { a.trials, a.sigDistinct, a.cond5, a.accepted, a.acceptedViolating5, a.rejectedSatisfying5, a.reasons };
    report["T3_pool9"] = new { b.trials, b.sigDistinct, b.cond5, b.accepted, b.acceptedViolating5, b.rejectedSatisfying5, b.disagreeWithIndependent, b.reasons };
}

// ---------------------------------------------------------------- T4
{
    int keys = Math.Min(n, 10000), dataBytes = 2000;
    long rejected = 0, acceptedSame = 0, acceptedDifferent = 0, otherErrors = 0, keysWithWrongBytes = 0, wrongBytes = 0, decodeErrors = 0;
    for (int k = 0; k < keys; k++)
    {
        var st = new AssocStego(et); var key = st.CreateKey();
        string path = Path.Combine(dir, "key_flip.bin");
        st.SaveKeyToFile(path, key);
        byte[] file = File.ReadAllBytes(path);
        // layout: magic, count, bit length (4 bytes each), then per mask: length (4 bytes) and the mask bytes
        int maskIndex = rng.Next(L), byteIndex = rng.Next(c), bit = rng.Next(8);
        int off = 12 + maskIndex * (4 + c) + 4 + byteIndex;
        file[off] ^= (byte)(1 << bit);
        File.WriteAllBytes(path, file);
        var st2 = new AssocStego(et);
        try { st2.LoadKeyFromFile(path); }
        catch (KeyValidationException) { rejected++; continue; }
        catch (Exception) { otherErrors++; continue; }
        bool same = Enumerable.Range(0, L).All(t => st2.Key[t] == key[t]);
        if (same) { acceptedSame++; continue; }
        acceptedDifferent++;
        var data = new byte[dataBytes]; rng.NextBytes(data);
        var block = new byte[st.HiddenByteLength]; long wrong = 0;
        for (int i = 0; i < data.Length; i++)
        {
            st.HideByteToBuffer(data[i], block);
            try { if (st2.DiscloseByteFromBuffer(block) != data[i]) wrong++; }
            catch (InvalidOperationException) { wrong++; decodeErrors++; }
        }
        if (wrong > 0) keysWithWrongBytes++;
        wrongBytes += wrong;
    }
    Console.WriteLine($"T4: {keys} key files with one flipped mask bit: rejected {rejected}; accepted unchanged {acceptedSame}; accepted as a different valid key {acceptedDifferent} " +
        $"(of which {keysWithWrongBytes} restore wrong bytes: {wrongBytes} of {acceptedDifferent * (long)dataBytes}, {decodeErrors} with a decoding error); other errors {otherErrors}");
    report["T4"] = new { keys, rejected, acceptedSame, acceptedDifferent, keysWithWrongBytes, wrongBytes, dataBytes, decodeErrors, otherErrors };
}

File.WriteAllText(Path.Combine(AppContext.BaseDirectory, "key_validation_results.json"), JsonSerializer.Serialize(report, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine(failures == 0 ? "ALL TESTS PASSED" : $"{failures} TEST(S) FAILED");
return failures == 0 ? 0 : 1;
